import { existsSync, readdirSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

/** Emit literal imports so Vite can bundle locale modules into its config. */
export function writeLocaleImporters(root: string): void {
  const localesDir = join(root, '.vitepress/locales')
  const locales = readdirSync(localesDir, { withFileTypes: true })
    .filter(entry => entry.isDirectory() && existsSync(join(localesDir, entry.name, 'config.ts')))
    .map(entry => entry.name)
    .sort()
  const lines = [
    '// Generated by pnpm init:locale. Keep literal imports for Vite config bundling.',
    'export const localeImporters = {',
    ...locales.map(locale => `  '${locale}': () => import('../locales/${locale}/config.ts'),`),
    '}',
    '',
  ]
  writeFileSync(join(root, '.vitepress/config/localeImporters.ts'), lines.join('\n'))
}
